CREATE TABLE app_user(id BIGSERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(254) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_user_email UNIQUE(email));
CREATE TABLE service_offering(id BIGSERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,duration_minutes INTEGER NOT NULL CHECK(duration_minutes>0),description TEXT,active BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE staff_profile(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL UNIQUE REFERENCES app_user(id),specialisation VARCHAR(255),active BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE staff_service(staff_id BIGINT NOT NULL REFERENCES staff_profile(id),service_id BIGINT NOT NULL REFERENCES service_offering(id),PRIMARY KEY(staff_id,service_id));
CREATE TABLE staff_availability(id BIGSERIAL PRIMARY KEY,staff_id BIGINT NOT NULL REFERENCES staff_profile(id),available_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CHECK(start_time<end_time));
CREATE INDEX idx_availability_staff_date ON staff_availability(staff_id,available_date);
CREATE TABLE appointment(id BIGSERIAL PRIMARY KEY,confirmation_number VARCHAR(20) NOT NULL UNIQUE,customer_id BIGINT NOT NULL REFERENCES app_user(id),staff_id BIGINT NOT NULL REFERENCES staff_profile(id),service_id BIGINT NOT NULL REFERENCES service_offering(id),appointment_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,status VARCHAR(30) NOT NULL,token_number VARCHAR(20),checked_in_at TIMESTAMPTZ,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,cancelled_at TIMESTAMPTZ,reminder_sent BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_appointment_slot UNIQUE(staff_id,appointment_date,start_time));
CREATE INDEX idx_appointment_customer ON appointment(customer_id); CREATE INDEX idx_appointment_staff_date ON appointment(staff_id,appointment_date); CREATE INDEX idx_appointment_service ON appointment(service_id); CREATE INDEX idx_appointment_status ON appointment(status);
CREATE TABLE queue_entry(id BIGSERIAL PRIMARY KEY,appointment_id BIGINT NOT NULL UNIQUE REFERENCES appointment(id),token_number VARCHAR(20) NOT NULL,status VARCHAR(30) NOT NULL,queue_position INTEGER NOT NULL,estimated_waiting_time_minutes INTEGER NOT NULL,joined_at TIMESTAMPTZ,called_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_queue_staff_status_joined ON queue_entry(status,joined_at);
CREATE TABLE queue_token_sequence(id BIGSERIAL PRIMARY KEY,sequence_date DATE NOT NULL,service_id BIGINT NOT NULL,next_value BIGINT NOT NULL,UNIQUE(sequence_date,service_id));
CREATE TABLE waitlist_entry(id BIGSERIAL PRIMARY KEY,customer_id BIGINT NOT NULL REFERENCES app_user(id),service_id BIGINT NOT NULL REFERENCES service_offering(id),preferred_staff_id BIGINT REFERENCES staff_profile(id),preferred_date DATE NOT NULL,preferred_start_time TIME NOT NULL,preferred_end_time TIME NOT NULL,status VARCHAR(30) NOT NULL,offered_appointment_id BIGINT REFERENCES appointment(id),offer_expires_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_waitlist_match ON waitlist_entry(service_id,preferred_date,status);
